/**
 * Billing report formatter. Renders records into the line format used by the
 * finance export.
 *
 * Field semantics follow docs/API.md as amended by docs/CHANGELOG.md (the
 * newest entry wins):
 * - `amount` and `discount` are integers in **cents**; both render as
 *   yuan with exactly two decimal places (v2.0/v2.1).
 * - `discount` carries the final discounted amount in cents and is rendered
 *   as-is — never computed from a rate (v2.1).
 * - `createdAt` is UTC epoch milliseconds; `created` renders as an ISO-8601
 *   string with an explicit `+08:00` offset (v2.3).
 */
const HEADER = 'id|name|amount|discount|created'

const TZ_OFFSET_MS = 8 * 60 * 60 * 1000 // +08:00 per docs/CHANGELOG.md v2.3

function formatCents(cents) {
  return ((cents ?? 0) / 100).toFixed(2)
}

function formatCreatedAt(epochMs) {
  // Shift the instant by +08:00, render the shifted wall clock as UTC, then
  // label it with the explicit offset so the output never depends on the
  // host machine's local timezone.
  const shifted = new Date((epochMs ?? 0) + TZ_OFFSET_MS)
  return shifted.toISOString().replace(/Z$/, '+08:00')
}

export function formatReport(records) {
  const lines = [HEADER]
  for (const record of records) {
    const name = record.name ?? '' // missing or invalid name renders empty (docs/FORMAT.md rule 4)
    const amount = formatCents(record.amount)
    const discount = formatCents(record.discount)
    const created = formatCreatedAt(record.createdAt)
    lines.push(`${record.id}|${name}|${amount}|${discount}|${created}`)
  }
  return lines
}
